# Servicio local: imprime etiqueta 21 (ZPL) en la PC de la impresora.
# Edita estas 2 lineas antes de instalar:

$QueueUrl = "http://CAMBIAR-IP-O-HOST/barcode4.0/print_queue_21.php"
$Printer  = "\\localhost\GK420t_chica"

$Key      = "barcode21"
$SleepSec = 3
$TempZpl  = Join-Path $env:TEMP "etiqueta21_job.zpl"

function Write-Log($msg) {
    $line = "{0} {1}" -f (Get-Date -Format "yyyy-MM-dd HH:mm:ss"), $msg
    Write-Host $line
}

Write-Log "Servicio etiqueta 21 iniciado. Cola=$QueueUrl Impresora=$Printer"

while ($true) {
    try {
        $pendingUrl = "$QueueUrl`?action=pending&key=$Key"
        $resp = Invoke-WebRequest -Uri $pendingUrl -UseBasicParsing -TimeoutSec 15
        $data = $resp.Content | ConvertFrom-Json
        if ($data.ok -and $data.jobs) {
            foreach ($job in $data.jobs) {
                Write-Log ("Imprimiendo job {0} item {1}" -f $job.id, $job.itemid)
                [System.IO.File]::WriteAllText($TempZpl, $job.zpl, [System.Text.Encoding]::ASCII)
                $copy = cmd /c "copy /b `"$TempZpl`" `"$Printer`""
                if ($LASTEXITCODE -ne 0) {
                    Write-Log "ERROR al enviar a impresora: $copy"
                    continue
                }
                $doneUrl = "$QueueUrl`?action=done&key=$Key&id=$($job.id)"
                Invoke-WebRequest -Uri $doneUrl -UseBasicParsing -TimeoutSec 15 | Out-Null
                Write-Log ("Job {0} impreso" -f $job.id)
            }
        }
    } catch {
        Write-Log ("Cola no disponible (PC/red/servidor): {0}" -f $_.Exception.Message)
    }
    Start-Sleep -Seconds $SleepSec
}

