# Servicio local etiqueta 21
# Lee la API JSON, imprime el ZPL y marca el trabajo como impreso.

$ApiUrl   = "http://CAMBIAR-IP-O-HOST/barcode4.0/api_print_21.php"
$Printer  = "\\localhost\GK420t_chica"
$ApiKey   = "barcode21"
$SleepSec = 3
$TempZpl  = Join-Path $env:TEMP "etiqueta21_job.zpl"

function Write-Log($msg) {
    Write-Host ("{0} {1}" -f (Get-Date -Format "yyyy-MM-dd HH:mm:ss"), $msg)
}

function Invoke-PrintApi {
    param(
        [string]$Url,
        [string]$Method = "GET",
        [string]$Body = $null
    )
    $headers = @{ "X-Api-Key" = $script:ApiKey }
    if ($Method -eq "POST") {
        return Invoke-RestMethod -Uri $Url -Method POST -Headers $headers -Body $Body -ContentType "application/json; charset=utf-8" -TimeoutSec 20
    }
    return Invoke-RestMethod -Uri $Url -Method GET -Headers $headers -TimeoutSec 20
}

Write-Log "API etiqueta 21: $ApiUrl"
Write-Log "Impresora: $Printer"

while ($true) {
    try {
        $pendingUrl = "$ApiUrl`?key=$ApiKey"
        $data = Invoke-PrintApi -Url $pendingUrl -Method "GET"
        if (-not $data.ok) {
            Write-Log "API ok=false"
        } elseif ($data.count -gt 0) {
            foreach ($job in $data.jobs) {
                Write-Log ("Pendiente id={0} item={1}" -f $job.id, $job.itemid)
                [System.IO.File]::WriteAllText($TempZpl, [string]$job.zpl, [System.Text.Encoding]::ASCII)
                cmd /c "copy /b `"$TempZpl`" `"$Printer`"" | Out-Null
                if ($LASTEXITCODE -ne 0) {
                    Write-Log "ERROR de impresora, no se marca como impreso"
                    $errBody = "{`"id`":$($job.id),`"estado`":`"error`"}"
                    try { Invoke-PrintApi -Url $pendingUrl -Method "POST" -Body $errBody | Out-Null } catch {}
                    continue
                }
                $okBody = "{`"id`":$($job.id),`"estado`":`"impreso`"}"
                $mark = Invoke-PrintApi -Url $pendingUrl -Method "POST" -Body $okBody
                if ($mark.ok) {
                    Write-Log ("Marcado impreso id={0}" -f $job.id)
                } else {
                    Write-Log ("No se pudo marcar impreso id={0}" -f $job.id)
                }
            }
        }
    } catch {
        Write-Log ("API no disponible: {0}" -f $_.Exception.Message)
    }
    Start-Sleep -Seconds $SleepSec
}

