/**
 * Fracción de tinta (negro) en una fila / columna del buffer 1-bit.
 */
function etiqueta10_row_ink($bits, $y)
{
	$w = $bits['w'];
	$h = $bits['h'];
	if ($y < 0 || $y >= $h || $w < 1) {
		return 1.0;
	}
	$ink = 0;
	$off = $y * $w;
	for ($x = 0; $x < $w; $x++) {
		if ($bits['p'][$off + $x] !== "\x00") {
			$ink++;
		}
	}
	return $ink / (float)$w;
}

function etiqueta10_col_ink($bits, $x)
{
	$w = $bits['w'];
	$h = $bits['h'];
	if ($x < 0 || $x >= $w || $h < 1) {
		return 1.0;
	}
	$ink = 0;
	for ($y = 0; $y < $h; $y++) {
		if ($bits['p'][$y * $w + $x] !== "\x00") {
			$ink++;
		}
	}
	return $ink / (float)$h;
}

