	$out = array('top' => 0, 'bottom' => 0, 'left' => 0, 'right' => 0);
	for ($y = $h - 1; $y >= 0; $y--) {
		if (etiqueta10_row_ink($bits, $y) > $maxInk) {
			break;
		}
		$out['bottom']++;
	}
	for ($y = 0; $y < $h; $y++) {
		if (etiqueta10_row_ink($bits, $y) > $maxInk) {
			break;
		}
		$out['top']++;
	}
	for ($x = $w - 1; $x >= 0; $x--) {
		if (etiqueta10_col_ink($bits, $x) > $maxInk) {
			break;
		}
		$out['right']++;
	}
	for ($x = 0; $x < $w; $x++) {
		if (etiqueta10_col_ink($bits, $x) > $maxInk) {
			break;
		}
		$out['left']++;
	}
	return $out;
}

/**
 * Layout automático: no usa x/y de lbl_lines.
 * - Detecta blanco en la imagen
 * - Reserva franja lateral para barcode (ahorra alto)
 * - Abajo: vencimiento, lote, reg. sanitario (si hay)
 * - Precio visible; código junto al barcode
 *
 * @return array{zpl:string,meta:array}
 */
function etiqueta10_auto_layout_zpl($srcBits, $pw, $ll, $barData, $ctx)
{
	$pw = max(80, (int)$pw);
	$ll = max(60, (int)$ll);

	// Análisis sobre un preview encajado al tamaño de etiqueta
	$preview = etiqueta10_resize_stretch($srcBits, $pw, $ll);
	$empty = etiqueta10_measure_empty($preview);

	// Franja lateral (preferir la más vacía)
	$side = 'right';
	$sideEmpty = (int)$empty['right'];
	if ((int)$empty['left'] > $sideEmpty + 10) {
		$side = 'left';
		$sideEmpty = (int)$empty['left'];
	}
	$sideW = $sideEmpty;
	if ($sideW < 58) {
		$sideW = (int)min(95, max(64, round($pw * 0.16)));
	} elseif ($sideW > 110) {
		$sideW = 110;
	}

	// Banda inferior para datos variables
	$botH = (int)$empty['bottom'];
	if ($botH < 44) {
		$botH = 50;
	} elseif ($botH > 78) {
		$botH = 78;
	}

	$gap = 3;
	$artW = $pw - $sideW - $gap;
	$artH = $ll - $botH - $gap;
	if ($artW < 40) {
		$artW = (int)($pw * 0.7);
		$sideW = $pw - $artW - $gap;
	}
	if ($artH < 40) {
		$artH = (int)($ll * 0.65);
		$botH = $ll - $artH - $gap;
	}
	$artX = ($side === 'left') ? ($sideW + $gap) : 0;
	$artY = 0;

	$artBits = etiqueta10_resize_contain($srcBits, $artW, $artH);
	$gfa = etiqueta10_to_gfa($artBits);
	$ox = $artX + (int)floor(($artW - $gfa['w']) / 2);
	$oy = $artY + (int)floor(($artH - $gfa['h']) / 2);
	if ($ox < $artX) {
		$ox = $artX;
	}
	if ($oy < $artY) {
		$oy = $artY;
	}

	$zpl = '';
	$zpl .= "^FO" . $ox . "," . $oy . "^GFA," . $gfa['total'] . "," . $gfa['total'] . "," . $gfa['bpr'] . "," . $gfa['hex'] . "^FS\n";

	// --- Barcode lateral (rotado) ---
	$barX = ($side === 'right') ? ($pw - $sideW + 6) : 4;
	$barY = 10;
	$barLen = max(40, $ll - $botH - 28); // largo del código a lo alto
	$barNarrow = ($sideW >= 85) ? 2 : 1;
	$zpl .= "^FO" . $barX . "," . $barY . "^BY" . $barNarrow . ",2," . $barLen . "\n";
	$zpl .= "^BCR," . $barLen . ",N,N,N\n^FD" . $barData . "^FS\n";

	// Código del producto junto/sobre el barcode (texto vertical corto en la franja)
	$itemid = isset($ctx['itemid']) ? etiqueta10_pad_codigo($ctx['itemid']) : $barData;
	$codeTxt = '[' . $itemid . ']';
	$hCode = 14;
	$codeX = ($side === 'right') ? ($pw - $sideW + 2) : 2;
	$codeY = max(2, $barY - 2);
	// Texto normal arriba de la franja (legible)
	$zpl .= "^FO" . $codeX . "," . $codeY . "^A0N," . $hCode . "," . $hCode . "^FD" . zpl_escape_field($codeTxt) . "^FS\n";

	// --- Banda inferior: precio + fechas + reg ---
	$y0 = $ll - $botH + 4;
	$x0 = 4;
	$precio = isset($ctx['precio']) ? (float)$ctx['precio'] : 0;
	$expir = isset($ctx['expir']) ? (int)$ctx['expir'] : 0;
	$reg = isset($ctx['reg_sanitario']) ? trim((string)$ctx['reg_sanitario']) : '';
	$base = etiqueta10_parse_fecha(isset($ctx['fecha_manufact']) ? $ctx['fecha_manufact'] : '');
	if ($base === false) {
		$base = time();
	}

	// Precio bien visible (derecha de la banda, o izquierda si barcode a la derecha ocupa)
	if ($precio != 0.0) {
		$priceTxt = 'B/.' . number_format($precio, 2, '.', ',');
		$hPrice = min(28, max(18, (int)floor($botH * 0.42)));
		$wPrice = (int)round($hPrice * 0.7);
		$priceX = max($x0, $pw - $sideW - (int)(strlen($priceTxt) * $wPrice * 0.55) - 8);
		if ($side === 'left') {
			$priceX = max($artX, $pw - (int)(strlen($priceTxt) * $wPrice * 0.55) - 6);
		}
		$zpl .= "^FO" . $priceX . "," . $y0 . "^A0N," . $hPrice . "," . $wPrice . "^FD" . zpl_escape_field($priceTxt) . "^FS\n";
	}

	$hMeta = min(16, max(12, (int)floor($botH * 0.28)));
	$wMeta = (int)round($hMeta * 0.55);
	$yMeta = $y0 + (($precio != 0.0) ? (int)round($botH * 0.38) : 2);
	if ($yMeta + $hMeta > $ll - 2) {
		$yMeta = $ll - $hMeta - 2;
	}

	if ($expir != 0) {
		$diaexp = date('d/m/Y', strtotime('+' . $expir . ' days', $base));
		$zpl .= "^FO" . $x0 . "," . $yMeta . "^A0N," . $hMeta . "," . $wMeta . "^FD" . zpl_escape_field('EXP:' . $diaexp) . "^FS\n";
		$loteTxt = 'Lote:' . etiqueta10_lote_code($base);
		$loteX = $x0 + (int)(strlen('EXP:' . $diaexp) * $wMeta * 0.62) + 10;
		if ($loteX > $pw - $sideW - 60) {
			$loteX = $x0;
			$yMeta2 = $yMeta + $hMeta + 1;
			if ($yMeta2 + $hMeta < $ll) {
				$zpl .= "^FO" . $loteX . "," . $yMeta2 . "^A0N," . $hMeta . "," . $wMeta . "^FD" . zpl_escape_field($loteTxt) . "^FS\n";
				$yMeta = $yMeta2;
			}
		} else {
			$zpl .= "^FO" . $loteX . "," . $yMeta . "^A0N," . $hMeta . "," . $wMeta . "^FD" . zpl_escape_field($loteTxt) . "^FS\n";
		}
	}

	if ($reg !== '' && $reg !== '0') {
		$yReg = $yMeta + $hMeta + 1;
		if ($yReg + $hMeta > $ll - 1) {
			$yReg = $ll - $hMeta - 1;
		}
		$zpl .= "^FO" . $x0 . "," . $yReg . "^A0N," . $hMeta . "," . $wMeta . "^FD" . zpl_escape_field('Reg:' . $reg) . "^FS\n";
	}

	return array(
		'zpl' => $zpl,
		'meta' => array(
			'side' => $side,
			'sideW' => $sideW,
			'botH' => $botH,
			'empty' => $empty,
			'auto' => true,
		),
	);
}

/**
 * @param string $barcode_data Código que va en el Code128 (itemid o itemid2). Vacío = $codigo.
 * @param array  $ctx         Datos variables (precio, fecha, etc.)
 * @param resource|null $link reservado (ya no se usan coords de lbl_lines)
 * @return array{ok:bool,zpl?:string,error?:string,path?:string,pw?:int,ll?:int,printer?:string}
 */
function build_zpl_etiqueta_10($codigo, $cant = 1, $lbls = array(), $barcode_data = '', $ctx = array(), $link = null)
{
	$codigo = etiqueta10_pad_codigo($codigo);
	$cant = (int)$cant;
	if ($cant < 1) {
		$cant = 1;
	}
	$barData = trim((string)$barcode_data);
	if ($barData === '') {
		$barData = $codigo;
	} else {
		$barDataDigits = preg_replace('/\D/', '', $barData);
		if ($barDataDigits !== '') {
			$barData = $barDataDigits;
		}
	}
	$path = etiqueta10_find_image($codigo);
	if ($path === '') {
		return array('ok' => false, 'error' => 'No hay imagen en printserver para ' . $codigo);
	}
	$loaded = etiqueta10_load_image($path);
	if (empty($loaded['ok'])) {
		return array('ok' => false, 'error' => isset($loaded['error']) ? $loaded['error'] : 'no se pudo leer imagen', 'path' => $path);
	}

	$printer = isset($lbls['printer']) ? trim((string)$lbls['printer']) : '';
	if (!empty($lbls['width']) && !empty($lbls['height'])) {
		$pw = max(1, etiqueta10_twips_to_dots($lbls['width']));
		$ll = max(1, etiqueta10_twips_to_dots($lbls['height']));
		if ($pw < $ll && $ll / $pw > 1.6) {
			$tmp = $pw;
			$pw = $ll;
			$ll = $tmp;
		}
	} else {
		$size = etiqueta10_parse_printer_size($printer);
		if ($size) {
			$pw = $size['w'];
			$ll = $size['h'];
		} else {
			$pw = $loaded['bits']['w'];
			$ll = $loaded['bits']['h'];
		}
	}

	if (!isset($ctx['itemid'])) {
		$ctx['itemid'] = $codigo;
	}

	$auto = etiqueta10_auto_layout_zpl($loaded['bits'], $pw, $ll, $barData, $ctx);

	$zpl = "^XA\n^FWN\n^PON\n^CI28\n^PW" . $pw . "\n^LL" . $ll . "\n^LH0,0\n";
	$zpl .= $auto['zpl'];
	$zpl .= "^PQ" . $cant . "\n^XZ\n";

	return array(
		'ok' => true,
		'zpl' => $zpl,
		'path' => $path,
		'pw' => $pw,
		'll' => $ll,
		'printer' => $printer,
		'img_w' => $loaded['bits']['w'],
		'img_h' => $loaded['bits']['h'],
		'layout' => isset($auto['meta']) ? $auto['meta'] : array(),
		'lines' => 0,
	);
}

/** Formato 14 VB6: igual que 10 (BMP) pero el código de barras es itemid2/codigo2. */
function build_zpl_etiqueta_14_bmp($codigo, $codigo2, $cant = 1, $lbls = array(), $ctx = array(), $link = null)
{
	return build_zpl_etiqueta_10($codigo, $cant, $lbls, $codigo2, $ctx, $link);
}

