/**
 * Textos variables de lbl_lines (como VB6 Imprimir_lbl10).
 * $sx/$sy escalan coords del espacio design_* al tamaño real del BMP en la etiqueta.
 */
function etiqueta10_append_lbl_lines(&$zpl, $lines, $ctx, $pw, $ll, $sx = 1.0, $sy = 1.0)
{
	if (!is_array($lines) || count($lines) === 0) {
		return;
	}
	if ($sx <= 0) {
		$sx = 1.0;
	}
	if ($sy <= 0) {
		$sy = 1.0;
	}
	$itemid = isset($ctx['itemid']) ? etiqueta10_pad_codigo($ctx['itemid']) : '';
	$precio = isset($ctx['precio']) ? (float)$ctx['precio'] : 0;
	$reg = isset($ctx['reg_sanitario']) ? (string)$ctx['reg_sanitario'] : '';
	$expir = isset($ctx['expir']) ? (int)$ctx['expir'] : 0;
	$base = etiqueta10_parse_fecha(isset($ctx['fecha_manufact']) ? $ctx['fecha_manufact'] : '');
	if ($base === false) {
		$base = time();
	}
	$diaexp = ($expir != 0) ? date('d/m/Y', strtotime('+' . $expir . ' days', $base)) : '';

	foreach ($lines as $line) {
		$field = isset($line['descrip']) ? strtolower(trim((string)$line['descrip'])) : '';
		$titulo = isset($line['titulo']) ? (string)$line['titulo'] : '';
		$x = (int)round(etiqueta10_twips_to_dots(isset($line['x']) ? $line['x'] : 0) * $sx);
		$y = (int)round(etiqueta10_twips_to_dots(isset($line['y']) ? $line['y'] : 0) * $sy);
		$h = max(10, (int)round(etiqueta10_font_dots(isset($line['font']) ? $line['font'] : 8) * min($sx, $sy)));
		$w = (int)round($h * 0.55);
		if ($w < 8) {
			$w = 8;
		}
		if ($x < 0) {
			$x = 0;
		}
		if ($y < 0 || $y >= $ll) {
			continue;
		}

		$text = '';
		$extraLote = '';
		// BMP ya trae nombre/ingredientes/contiene — solo variables
		if ($field === 'descripcion' || $field === 'ingredientes' || $field === 'especif' || $field === 'obs') {
			continue;
		} elseif ($field === 'itemid') {
			$text = $titulo . '[' . $itemid . ']';
		} elseif ($field === 'precio') {
			if ($precio == 0.0) {
				continue;
			}
			$text = $titulo . number_format($precio, 2, '.', ',');
		} elseif ($field === 'fecha') {
			if ($expir == 0 || $diaexp === '') {
				continue;
			}
			$text = $titulo . $diaexp;
			$extraLote = 'Lote: ' . etiqueta10_lote_code($base);
		} elseif ($field === 'reg_sanitario') {
			if ($reg === '' || $reg === '0') {
				continue;
			}
			$text = $titulo . $reg;
		} else {
			continue;
		}

		$text = trim($text);
		if ($text === '') {
			continue;
		}

		if ($x + 20 > $pw) {
			$x = max(0, $pw - 80);
		}
		$zpl .= "^FO" . $x . "," . $y . "^A0N," . $h . "," . $w . "^FD" . zpl_escape_field($text) . "^FS\n";
		if ($extraLote !== '') {
			$yLote = $y + (int)round(etiqueta10_twips_to_dots(150) * $sy);
			if ($yLote + $h < $ll) {
				$zpl .= "^FO" . $x . "," . $yLote . "^A0N," . $h . "," . $w . "^FD" . zpl_escape_field($extraLote) . "^FS\n";
			}
		}
	}
}

/**
 * @param string $barcode_data Código que va en el Code128 (itemid o itemid2). Vacío = $codigo.
 * @param array  $ctx         Datos variables (precio, fecha, etc.) + opcional 'lines' o se leen de $link
 * @param resource|null $link MySQL para lbl_lines
 * @return array{ok:bool,zpl?:string,error?:string,path?:string,pw?:int,ll?:int,printer?:string}
 */
function build_zpl_etiqueta_10($codigo, $cant = 1, $lbls = array(), $barcode_data = '', $ctx = array(), $link = null)
{
	$codigo = etiqueta10_pad_codigo($codigo);
	$cant = (int)$cant;
	if ($cant < 1) {
		$cant = 1;
	}
	$barData = trim((string)$barcode_data);
	if ($barData === '') {
		$barData = $codigo;
	} else {
		$barDataDigits = preg_replace('/\D/', '', $barData);
		if ($barDataDigits !== '') {
			$barData = $barDataDigits;
		}
	}
	$path = etiqueta10_find_image($codigo);
	if ($path === '') {
		return array('ok' => false, 'error' => 'No hay imagen en printserver para ' . $codigo);
	}
	$loaded = etiqueta10_load_image($path);
	if (empty($loaded['ok'])) {
		return array('ok' => false, 'error' => isset($loaded['error']) ? $loaded['error'] : 'no se pudo leer imagen', 'path' => $path);
	}

	$printer = isset($lbls['printer']) ? trim((string)$lbls['printer']) : '';
	// 1) Datos guardados en lbls (twips)  2) tamaño en nombre de impresora  3) BMP
	if (!empty($lbls['width']) && !empty($lbls['height'])) {
		$pw = max(1, etiqueta10_twips_to_dots($lbls['width']));
		$ll = max(1, etiqueta10_twips_to_dots($lbls['height']));
		if ($pw < $ll && $ll / $pw > 1.6) {
			$tmp = $pw;
			$pw = $ll;
			$ll = $tmp;
		}
	} else {
		$size = etiqueta10_parse_printer_size($printer);
		if ($size) {
			$pw = $size['w'];
			$ll = $size['h'];
		} else {
			$pw = $loaded['bits']['w'];
			$ll = $loaded['bits']['h'];
		}
	}

	$dx = !empty($lbls['design_x']) ? etiqueta10_twips_to_dots($lbls['design_x']) : 0;
	$dy = !empty($lbls['design_y']) ? etiqueta10_twips_to_dots($lbls['design_y']) : 0;
	$dw = !empty($lbls['design_width']) ? etiqueta10_twips_to_dots($lbls['design_width']) : $pw;
	$dh = !empty($lbls['design_height']) ? etiqueta10_twips_to_dots($lbls['design_height']) : $ll;
	if ($dx < 0) {
		$dx = 0;
	}
	if ($dy < 0) {
		$dy = 0;
	}
	if ($dw < 8) {
		$dw = $pw;
	}
	if ($dh < 8) {
		$dh = $ll;
	}

	// Encajar arte completo en la etiqueta (evita recortar ingredientes sobre el barcode).
	// Escala barras y lbl_lines con el mismo factor que el BMP.
	$fitW = $pw;
	$fitH = $ll;
	$sx = $fitW / (float)$dw;
	$sy = $fitH / (float)$dh;
	$fitted = etiqueta10_resize_stretch($loaded['bits'], $fitW, $fitH);
	$gfa = etiqueta10_to_gfa($fitted);
	$ox = 0;
	$oy = 0;

	$bx = isset($lbls['bar_x']) && $lbls['bar_x'] !== '' && $lbls['bar_x'] !== null
		? (int)round(etiqueta10_twips_to_dots($lbls['bar_x']) * $sx) : -1;
	$by = isset($lbls['bar_y']) && $lbls['bar_y'] !== '' && $lbls['bar_y'] !== null
		? (int)round(etiqueta10_twips_to_dots($lbls['bar_y']) * $sy) : -1;
	$bw = !empty($lbls['bar_width']) ? (int)round(etiqueta10_twips_to_dots($lbls['bar_width']) * $sx) : 0;
	$bh = !empty($lbls['bar_height']) ? (int)round(etiqueta10_twips_to_dots($lbls['bar_height']) * $sy) : 0;
	$useBar = ($bx >= 0 && $by >= 0 && $bw > 20 && $bh > 10 && $by < $ll);

	$zpl = "^XA\n^FWN\n^PON\n^CI28\n^PW" . $pw . "\n^LL" . $ll . "\n^LH0,0\n";
	$zpl .= "^FO" . $ox . "," . $oy . "^GFA," . $gfa['total'] . "," . $gfa['total'] . "," . $gfa['bpr'] . "," . $gfa['hex'] . "^FS\n";

	if ($useBar) {
		if ($bx + $bw > $pw) {
			$bw = $pw - $bx;
		}
		if ($by + $bh > $ll) {
			$bh = $ll - $by - 2;
		}
		if ($bh < 18) {
			$bh = 18;
		}
		if ($bw > 30 && $bh > 12) {
			$zpl .= "^FO" . $bx . "," . $by . "^BY2,2," . $bh . "\n";
			$zpl .= "^BCN," . $bh . ",N,N,N\n^FD" . $barData . "^FS\n";
		}
	}

	if (!isset($ctx['itemid'])) {
		$ctx['itemid'] = $codigo;
	}
	$lines = array();
	if (isset($ctx['lines']) && is_array($ctx['lines'])) {
		$lines = $ctx['lines'];
	} elseif ($link) {
		$lines = etiqueta10_lookup_lines($link, $codigo);
	}
	etiqueta10_append_lbl_lines($zpl, $lines, $ctx, $pw, $ll, $sx, $sy);

	$zpl .= "^PQ" . $cant . "\n^XZ\n";
	return array(
		'ok' => true,
		'zpl' => $zpl,
		'path' => $path,
		'pw' => $pw,
		'll' => $ll,
		'printer' => $printer,
		'img_w' => $loaded['bits']['w'],
		'img_h' => $loaded['bits']['h'],
		'lines' => count($lines),
	);
}

/** Formato 14 VB6: igual que 10 (BMP) pero el código de barras es itemid2/codigo2. */
function build_zpl_etiqueta_14_bmp($codigo, $codigo2, $cant = 1, $lbls = array(), $ctx = array(), $link = null)
{
	return build_zpl_etiqueta_10($codigo, $cant, $lbls, $codigo2, $ctx, $link);
}

