$lay = isset($built10['layout']) ? $built10['layout'] : array();
$sideInfo = isset($lay['side']) ? ($lay['side'] . '/' . (isset($lay['sideW']) ? $lay['sideW'] : '?')) : 'auto';
echo "<br>Etiqueta 10 en cola (id $qid). Imagen: " . htmlspecialchars(basename($built10['path'])) . ". Layout auto (barra " . htmlspecialchars($sideInfo) . ").<br>";

/**
 * Layout automático: no usa x/y de lbl_lines.
 * - Barcode lateral mínimo usable (^BY1, altura ~24)
 * - Máximo espacio para arte + precio/EXP/lote/reg
 * - Código [itemid] en banda de datos (no ensancha la franja)
 *
 * @return array{zpl:string,meta:array}
 */
function etiqueta10_auto_layout_zpl($srcBits, $pw, $ll, $barData, $ctx)
{
	$pw = max(80, (int)$pw);
	$ll = max(60, (int)$ll);

	$preview = etiqueta10_resize_stretch($srcBits, $pw, $ll);
	$empty = etiqueta10_measure_empty($preview);

	// Lado con más blanco (solo decide izq/der; el ancho del barcode es fijo mínimo)
	$side = 'right';
	if ((int)$empty['left'] > (int)$empty['right'] + 10) {
		$side = 'left';
	}

	// Barcode lo más chico posible pero escaneable: módulo 1, barras ~24 dots
	$barH = 24;
	$sidePad = 4;
	$sideW = $barH + $sidePad + 2; // ~30 dots de franja

	// Banda inferior: más espacio para datos (precio, código, EXP, lote, reg)
	$botH = (int)$empty['bottom'];
	if ($botH < 52) {
		$botH = 56;
	} elseif ($botH > 90) {
		$botH = 90;
	}

