/**
 * Busca el mayor rectángulo casi blanco (para poner datos variables sobre el BMP).
 * Prefiere zona inferior (y opcionalmente izquierda).
 *
 * @return array{x:int,y:int,w:int,h:int}|null
 */
function etiqueta10_find_white_rect($bits, $preferLeft = true)
{
	$w = $bits['w'];
	$h = $bits['h'];
	if ($w < 20 || $h < 20) {
		return null;
	}
	$maxInk = 0.08;
	$best = null;
	$bestArea = 0;
	$y0 = (int)floor($h * 0.35); // solo mitad/inferior del arte
	$step = max(2, (int)floor(min($w, $h) / 40));

	for ($top = $y0; $top < $h - 18; $top += $step) {
		for ($bot = $h - 1; $bot > $top + 16; $bot -= $step) {
			$rh = $bot - $top + 1;
			// filas candidatas: deben ser mayormente blancas
			$bad = false;
			for ($y = $top; $y <= $bot; $y += max(1, (int)floor($rh / 8))) {
				if (etiqueta10_row_ink($bits, $y) > $maxInk * 2.5) {
					$bad = true;
					break;
				}
			}
			if ($bad) {
				continue;
			}
			$xStart = $preferLeft ? 0 : (int)floor($w * 0.15);
			$xEnd = $preferLeft ? (int)floor($w * 0.72) : $w - 1;
			for ($left = $xStart; $left < $xEnd - 40; $left += $step) {
				for ($right = $xEnd; $right > $left + 40; $right -= $step) {
					$rw = $right - $left + 1;
					$ink = 0;
					$samples = 0;
					for ($y = $top; $y <= $bot; $y += max(1, (int)floor($rh / 6))) {
						for ($x = $left; $x <= $right; $x += max(1, (int)floor($rw / 8))) {
							$samples++;
							if ($bits['p'][$y * $w + $x] !== "\x00") {
								$ink++;
							}
						}
					}
					if ($samples < 1) {
						continue;
					}
					if (($ink / (float)$samples) > $maxInk) {
						continue;
					}
					$area = $rw * $rh;
					// bonus zona baja e izquierda
					$bonus = 1.0 + (0.35 * ($top / (float)$h)) + ($preferLeft ? (0.15 * (1.0 - ($left / (float)$w))) : 0);
					$score = $area * $bonus;
					if ($score > $bestArea) {
						$bestArea = $score;
						$best = array('x' => $left, 'y' => $top, 'w' => $rw, 'h' => $rh);
					}
					break; // primer right válido lo bastante ancho
				}
			}
		}
	}
	return $best;
}

/**
 * Layout automático:
 * - BMP ocupa casi toda la etiqueta
 * - Solo una franja fina lateral para barcode mínimo
 * - Precio / código / EXP / lote / reg se colocan en huecos blancos del BMP
 *
 * @return array{zpl:string,meta:array}
 */
function etiqueta10_auto_layout_zpl($srcBits, $pw, $ll, $barData, $ctx)
{
	$pw = max(80, (int)$pw);
	$ll = max(60, (int)$ll);

	$preview = etiqueta10_resize_stretch($srcBits, $pw, $ll);
	$empty = etiqueta10_measure_empty($preview);

	// Franja mínima para barcode (no comerse el BMP)
	$side = 'left';
	if ((int)$empty['right'] > (int)$empty['left'] + 15) {
		$side = 'right';
	}
	$barH = 22; // grosor útil mínimo del barcode rotado
	$sideW = $barH + 6; // ~28 dots

	$gap = 2;
	$artW = $pw - $sideW - $gap;
	$artH = $ll; // casi toda la altura = el BMP
	$artX = ($side === 'left') ? ($sideW + $gap) : 0;
	$artY = 0;

	// Arte a casi toda la etiqueta (sin banda inferior reservada)
	$artBits = etiqueta10_resize_stretch($srcBits, $artW, $artH);
	$gfa = etiqueta10_to_gfa($artBits);
	$ox = $artX;
	$oy = $artY;

	$zpl = '';
	$zpl .= "^FO" . $ox . "," . $oy . "^GFA," . $gfa['total'] . "," . $gfa['total'] . "," . $gfa['bpr'] . "," . $gfa['hex'] . "^FS\n";

	// Barcode fino lateral
	$barX = ($side === 'left') ? 2 : ($pw - $sideW + 2);
	$barY = 4;
	$zpl .= "^FO" . $barX . "," . $barY . "^BY1,2," . $barH . "\n";
	$zpl .= "^BCR," . $barH . ",N,N,N\n^FD" . $barData . "^FS\n";

	$itemid = isset($ctx['itemid']) ? etiqueta10_pad_codigo($ctx['itemid']) : $barData;
	$codeTxt = '[' . $itemid . ']';
	$precio = isset($ctx['precio']) ? (float)$ctx['precio'] : 0;
	$expir = isset($ctx['expir']) ? (int)$ctx['expir'] : 0;
	$reg = isset($ctx['reg_sanitario']) ? trim((string)$ctx['reg_sanitario']) : '';
	$base = etiqueta10_parse_fecha(isset($ctx['fecha_manufact']) ? $ctx['fecha_manufact'] : '');
	if ($base === false) {
		$base = time();
	}

	// Hueco blanco DENTRO del BMP para los datos (no recorta el arte)
	$slot = etiqueta10_find_white_rect($artBits, true);
	if ($slot === null) {
		// fallback: esquina inferior del arte según margen blanco medido
		$bh = max(36, min(70, (int)$empty['bottom'] + 8));
		$slot = array(
			'x' => 4,
			'y' => max(0, $artH - $bh),
			'w' => max(80, (int)floor($artW * 0.55)),
			'h' => $bh,
		);
	}

	$sx = $artX + (int)$slot['x'] + 2;
	$sy = $artY + (int)$slot['y'] + 2;
	$sw = max(40, (int)$slot['w'] - 4);
	$sh = max(28, (int)$slot['h'] - 4);

	// Precio visible (arriba del hueco / primera línea)
	$y = $sy;
	if ($precio != 0.0) {
		$priceTxt = 'B/.' . number_format($precio, 2, '.', ',');
		$hPrice = min(26, max(16, (int)floor($sh * 0.38)));
		$wPrice = (int)round($hPrice * 0.7);
		$zpl .= "^FO" . $sx . "," . $y . "^A0N," . $hPrice . "," . $wPrice . "^FD" . zpl_escape_field($priceTxt) . "^FS\n";
		$codeX = $sx + (int)(strlen($priceTxt) * $wPrice * 0.55) + 6;
		$hCode = min(16, max(12, $hPrice - 6));
		if ($codeX + 55 < $sx + $sw) {
			$zpl .= "^FO" . $codeX . "," . ($y + 2) . "^A0N," . $hCode . "," . $hCode . "^FD" . zpl_escape_field($codeTxt) . "^FS\n";
		} else {
			$y += $hPrice + 1;
			$zpl .= "^FO" . $sx . "," . $y . "^A0N," . $hCode . "," . $hCode . "^FD" . zpl_escape_field($codeTxt) . "^FS\n";
		}
		$y += $hPrice + 2;
	} else {
		$hCode = 14;
		$zpl .= "^FO" . $sx . "," . $y . "^A0N," . $hCode . "," . $hCode . "^FD" . zpl_escape_field($codeTxt) . "^FS\n";
		$y += $hCode + 2;
	}

	$hMeta = min(14, max(11, (int)floor($sh * 0.22)));
	$wMeta = (int)round($hMeta * 0.55);
	if ($y + $hMeta > $sy + $sh) {
		$y = max($sy, $sy + $sh - ($hMeta * 3) - 2);
	}

	if ($expir != 0) {
		$diaexp = date('d/m/Y', strtotime('+' . $expir . ' days', $base));
		$expTxt = 'EXP:' . $diaexp;
		$zpl .= "^FO" . $sx . "," . $y . "^A0N," . $hMeta . "," . $wMeta . "^FD" . zpl_escape_field($expTxt) . "^FS\n";
		$loteTxt = 'Lote:' . etiqueta10_lote_code($base);
		$loteX = $sx + (int)(strlen($expTxt) * $wMeta * 0.62) + 6;
		if ($loteX + 48 < $sx + $sw) {
			$zpl .= "^FO" . $loteX . "," . $y . "^A0N," . $hMeta . "," . $wMeta . "^FD" . zpl_escape_field($loteTxt) . "^FS\n";
			$y += $hMeta + 1;
		} else {
			$y += $hMeta + 1;
			$zpl .= "^FO" . $sx . "," . $y . "^A0N," . $hMeta . "," . $wMeta . "^FD" . zpl_escape_field($loteTxt) . "^FS\n";
			$y += $hMeta + 1;
		}
	}

	if ($reg !== '' && $reg !== '0') {
		if ($y + $hMeta > $sy + $sh) {
			$y = $sy + $sh - $hMeta;
		}
		$zpl .= "^FO" . $sx . "," . $y . "^A0N," . $hMeta . "," . $wMeta . "^FD" . zpl_escape_field('Reg:' . $reg) . "^FS\n";
	}

	return array(
		'zpl' => $zpl,
		'meta' => array(
			'side' => $side,
			'sideW' => $sideW,
			'barH' => $barH,
			'slot' => $slot,
			'empty' => $empty,
			'auto' => true,
		),
	);
}

