	// Barcode lo más chico posible pero escaneable: módulo 1, barras ~24 dots
	$barH = 24;
	$sidePad = 4;
	$sideW = $barH + $sidePad + 2; // ~30 dots de franja

	// Banda inferior: más espacio para datos (precio, código, EXP, lote, reg)
	$botH = (int)$empty['bottom'];
	if ($botH < 52) {
		$botH = 56;
	} elseif ($botH > 90) {
		$botH = 90;
	}

	$gap = 2;
	$artW = $pw - $sideW - $gap;
	$artH = $ll - $botH - $gap;
	if ($artW < 50) {
		$artW = (int)($pw * 0.88);
		$sideW = max(28, $pw - $artW - $gap);
		$barH = max(18, $sideW - $sidePad - 2);
	}
	if ($artH < 40) {
		$artH = (int)($ll * 0.62);
		$botH = $ll - $artH - $gap;
	}
	$artX = ($side === 'left') ? ($sideW + $gap) : 0;
	$artY = 0;

	$artBits = etiqueta10_resize_contain($srcBits, $artW, $artH);
	$gfa = etiqueta10_to_gfa($artBits);
	$ox = $artX + (int)floor(($artW - $gfa['w']) / 2);
	$oy = $artY + (int)floor(($artH - $gfa['h']) / 2);
	if ($ox < $artX) {
		$ox = $artX;
	}
	if ($oy < $artY) {
		$oy = $artY;
	}

	$zpl = '';
	$zpl .= "^FO" . $ox . "," . $oy . "^GFA," . $gfa['total'] . "," . $gfa['total'] . "," . $gfa['bpr'] . "," . $gfa['hex'] . "^FS\n";

	// Barcode lateral mínimo (rotado). El largo a lo alto lo define el dato + ^BY1.
	$barX = ($side === 'right') ? ($pw - $sideW + 2) : 2;
	$barY = 6;
	$zpl .= "^FO" . $barX . "," . $barY . "^BY1,2," . $barH . "\n";
	$zpl .= "^BCR," . $barH . ",N,N,N\n^FD" . $barData . "^FS\n";

	$itemid = isset($ctx['itemid']) ? etiqueta10_pad_codigo($ctx['itemid']) : $barData;
	$codeTxt = '[' . $itemid . ']';
	$precio = isset($ctx['precio']) ? (float)$ctx['precio'] : 0;
	$expir = isset($ctx['expir']) ? (int)$ctx['expir'] : 0;
	$reg = isset($ctx['reg_sanitario']) ? trim((string)$ctx['reg_sanitario']) : '';
	$base = etiqueta10_parse_fecha(isset($ctx['fecha_manufact']) ? $ctx['fecha_manufact'] : '');
	if ($base === false) {
		$base = time();
	}

	// --- Banda inferior: todo el espacio de datos ---
	$y0 = $ll - $botH + 3;
	$x0 = 3;
	$metaRight = $pw - $sideW - 4;

	// Precio grande y visible
	$xCursor = $x0;
	if ($precio != 0.0) {
		$priceTxt = 'B/.' . number_format($precio, 2, '.', ',');
		$hPrice = min(30, max(20, (int)floor($botH * 0.45)));
		$wPrice = (int)round($hPrice * 0.72);
		$zpl .= "^FO" . $x0 . "," . $y0 . "^A0N," . $hPrice . "," . $wPrice . "^FD" . zpl_escape_field($priceTxt) . "^FS\n";
		$xCursor = $x0 + (int)(strlen($priceTxt) * $wPrice * 0.58) + 8;
	}

	// Código del producto al lado del precio (misma fila si cabe)
	$hCode = min(18, max(14, (int)floor($botH * 0.32)));
	$codeX = $xCursor;
	if ($codeX + 50 > $metaRight) {
		$codeX = $x0;
		$yCode = $y0 + (($precio != 0.0) ? (int)round($botH * 0.42) : 0);
	} else {
		$yCode = $y0 + (int)max(0, (($precio != 0.0) ? (int)floor($botH * 0.08) : 0));
	}
	$zpl .= "^FO" . $codeX . "," . $yCode . "^A0N," . $hCode . "," . $hCode . "^FD" . zpl_escape_field($codeTxt) . "^FS\n";

	$hMeta = min(15, max(11, (int)floor($botH * 0.24)));
	$wMeta = (int)round($hMeta * 0.55);
	$yMeta = $y0 + (int)round($botH * 0.48);
	if ($yMeta + $hMeta > $ll - 2) {
		$yMeta = $ll - $hMeta - 2;
	}

	if ($expir != 0) {
		$diaexp = date('d/m/Y', strtotime('+' . $expir . ' days', $base));
		$expTxt = 'EXP:' . $diaexp;
		$zpl .= "^FO" . $x0 . "," . $yMeta . "^A0N," . $hMeta . "," . $wMeta . "^FD" . zpl_escape_field($expTxt) . "^FS\n";
		$loteTxt = 'Lote:' . etiqueta10_lote_code($base);
		$loteX = $x0 + (int)(strlen($expTxt) * $wMeta * 0.62) + 8;
		if ($loteX + 50 > $metaRight) {
			$yMeta2 = $yMeta + $hMeta + 1;
			if ($yMeta2 + $hMeta < $ll) {
				$zpl .= "^FO" . $x0 . "," . $yMeta2 . "^A0N," . $hMeta . "," . $wMeta . "^FD" . zpl_escape_field($loteTxt) . "^FS\n";
				$yMeta = $yMeta2;
			}
		} else {
			$zpl .= "^FO" . $loteX . "," . $yMeta . "^A0N," . $hMeta . "," . $wMeta . "^FD" . zpl_escape_field($loteTxt) . "^FS\n";
		}
	}

	if ($reg !== '' && $reg !== '0') {
		$yReg = $yMeta + $hMeta + 1;
		if ($yReg + $hMeta > $ll - 1) {
			$yReg = $ll - $hMeta - 1;
		}
		$zpl .= "^FO" . $x0 . "," . $yReg . "^A0N," . $hMeta . "," . $wMeta . "^FD" . zpl_escape_field('Reg:' . $reg) . "^FS\n";
	}

	return array(
		'zpl' => $zpl,
		'meta' => array(
			'side' => $side,
			'sideW' => $sideW,
			'barH' => $barH,
			'botH' => $botH,
			'empty' => $empty,
			'auto' => true,
		),
	);
}

