* Layout: BMP casi a etiqueta completa; barcode fino lateral;
* precio/EXP/lote/reg en huecos blancos detectados dentro del BMP.
*/

/**
 * ¿La zona (x,y,w,h) está lo bastante limpia (poca tinta)?
 */
function etiqueta10_region_is_clear($bits, $x, $y, $rw, $rh, $maxInk = 0.10)
{
	$w = $bits['w'];
	$h = $bits['h'];
	$x = max(0, (int)$x);
	$y = max(0, (int)$y);
	$rw = max(1, (int)$rw);
	$rh = max(1, (int)$rh);
	if ($x >= $w || $y >= $h) {
		return false;
	}
	if ($x + $rw > $w) {
		$rw = $w - $x;
	}
	if ($y + $rh > $h) {
		$rh = $h - $y;
	}
	if ($rw < 8 || $rh < 10) {
		return false;
	}
	$ink = 0;
	$n = 0;
	$ys = max(1, (int)floor($rh / 10));
	$xs = max(1, (int)floor($rw / 12));
	for ($yy = $y; $yy < $y + $rh; $yy += $ys) {
		for ($xx = $x; $xx < $x + $rw; $xx += $xs) {
			$n++;
			if ($bits['p'][$yy * $w + $xx] !== "\x00") {
				$ink++;
			}
		}
	}
	return $n > 0 && ($ink / (float)$n) <= $maxInk;
}

/**
 * Ancla preferida + si choca con el arte, busca hueco cercano y se ajusta al espacio.
 * Preferencia: abajo-izquierda (datos), con fallbacks a la derecha/arriba dentro de la zona baja.
 *
 * @return array{x:int,y:int,w:int,h:int,moved:bool,method:string}
 */
function etiqueta10_resolve_data_slot($bits, $needW, $needH)
{
	$w = $bits['w'];
	$h = $bits['h'];
	$needW = max(70, min($needW, (int)floor($w * 0.70)));
	$needH = max(34, min($needH, (int)floor($h * 0.45)));

	// 1) Lugar específico preferido: esquina inferior izquierda
	$pref = array(
		'x' => 3,
		'y' => max(0, $h - $needH - 4),
		'w' => $needW,
		'h' => $needH,
	);
	if (etiqueta10_region_is_clear($bits, $pref['x'], $pref['y'], $pref['w'], $pref['h'])) {
		$pref['moved'] = false;
		$pref['method'] = 'anchor';
		return $pref;
	}

	// 2) Si cae sobre arte: probar desplazamientos (derecha / subir / achicar)
	$candidates = array();
	$shiftsX = array(0, 20, 40, 60, 80, 100, (int)floor($w * 0.25), (int)floor($w * 0.40));
	$shiftsY = array(0, -8, -16, -28, -40, -55, -70);
	$sizes = array(
		array($needW, $needH),
		array((int)floor($needW * 0.85), $needH),
		array((int)floor($needW * 0.75), (int)floor($needH * 0.85)),
		array((int)floor($needW * 0.65), (int)floor($needH * 0.75)),
		array(90, 36),
		array(80, 32),
	);

	foreach ($sizes as $sz) {
		$sw = $sz[0];
		$sh = $sz[1];
		foreach ($shiftsY as $dy) {
			foreach ($shiftsX as $dx) {
				$x = 3 + $dx;
				$y = $h - $sh - 4 + $dy;
				if ($x < 0 || $y < (int)floor($h * 0.25)) {
					continue;
				}
				if ($x + $sw > $w - 2) {
					continue;
				}
				if ($y + $sh > $h - 1) {
					continue;
				}
				if (!etiqueta10_region_is_clear($bits, $x, $y, $sw, $sh, 0.11)) {
					continue;
				}
				// score: más abajo e izquierda = mejor; más grande = mejor
				$score = ($y / (float)$h) * 2.0 + (1.0 - ($x / (float)$w)) + ($sw * $sh) / (float)($w * $h) * 3.0;
				$candidates[] = array('x' => $x, 'y' => $y, 'w' => $sw, 'h' => $sh, 'score' => $score);
			}
		}
	}

	if (count($candidates) > 0) {
		usort($candidates, function ($a, $b) {
			if ($a['score'] == $b['score']) {
				return 0;
			}
			return ($a['score'] > $b['score']) ? -1 : 1;
		});
		$best = $candidates[0];
		return array(
			'x' => (int)$best['x'],
			'y' => (int)$best['y'],
			'w' => (int)$best['w'],
			'h' => (int)$best['h'],
			'moved' => true,
			'method' => 'shifted',
		);
	}

	// 3) Último recurso: detector de rectángulo blanco / ancla aunque no esté perfecta
	$found = etiqueta10_find_white_rect($bits, true);
	if ($found) {
		$found['moved'] = true;
		$found['method'] = 'detected';
		return $found;
	}

	$pref['moved'] = true;
	$pref['method'] = 'forced';
	return $pref;
}

/**
 * Layout automático:
 * - BMP ocupa casi toda la etiqueta
 * - Franja fina lateral solo para barcode
 * - Datos: ancla fija abajo-izq; si pisa el arte, se mueve al hueco libre y se achica al espacio
 *
 * @return array{zpl:string,meta:array}
 */
function etiqueta10_auto_layout_zpl($srcBits, $pw, $ll, $barData, $ctx)
{
	$pw = max(80, (int)$pw);
	$ll = max(60, (int)$ll);

	$preview = etiqueta10_resize_stretch($srcBits, $pw, $ll);
	$empty = etiqueta10_measure_empty($preview);

	$side = 'left';
	if ((int)$empty['right'] > (int)$empty['left'] + 15) {
		$side = 'right';
	}
	$barH = 22;
	$sideW = $barH + 6;

	$gap = 2;
	$artW = $pw - $sideW - $gap;
	$artH = $ll;
	$artX = ($side === 'left') ? ($sideW + $gap) : 0;
	$artY = 0;

	$artBits = etiqueta10_resize_stretch($srcBits, $artW, $artH);
	$gfa = etiqueta10_to_gfa($artBits);

	$zpl = '';
	$zpl .= "^FO" . $artX . "," . $artY . "^GFA," . $gfa['total'] . "," . $gfa['total'] . "," . $gfa['bpr'] . "," . $gfa['hex'] . "^FS\n";

	$barX = ($side === 'left') ? 2 : ($pw - $sideW + 2);
	$zpl .= "^FO" . $barX . ",4^BY1,2," . $barH . "\n";
	$zpl .= "^BCR," . $barH . ",N,N,N\n^FD" . $barData . "^FS\n";

	$itemid = isset($ctx['itemid']) ? etiqueta10_pad_codigo($ctx['itemid']) : $barData;
	$codeTxt = '[' . $itemid . ']';
	$precio = isset($ctx['precio']) ? (float)$ctx['precio'] : 0;
	$expir = isset($ctx['expir']) ? (int)$ctx['expir'] : 0;
	$reg = isset($ctx['reg_sanitario']) ? trim((string)$ctx['reg_sanitario']) : '';
	$base = etiqueta10_parse_fecha(isset($ctx['fecha_manufact']) ? $ctx['fecha_manufact'] : '');
	if ($base === false) {
		$base = time();
	}

	// Espacio deseado para: precio + código + EXP/lote + reg
	$linesNeeded = 1 + (($expir != 0) ? 2 : 0) + (($reg !== '' && $reg !== '0') ? 1 : 0);
	$needH = 18 + ($linesNeeded * 14);
	$needW = (int)min($artW - 8, max(120, (int)floor($artW * 0.55)));

	$slot = etiqueta10_resolve_data_slot($artBits, $needW, $needH);
	$sx = $artX + (int)$slot['x'] + 2;
	$sy = $artY + (int)$slot['y'] + 2;
	$sw = max(40, (int)$slot['w'] - 4);
	$sh = max(28, (int)$slot['h'] - 4);

	$y = $sy;
	$xMax = $sx + $sw;

	if ($precio != 0.0) {
		$priceTxt = 'B/.' . number_format($precio, 2, '.', ',');
		$hPrice = min(26, max(15, (int)floor($sh * 0.36)));
		$wPrice = (int)round($hPrice * 0.7);
		// Si no cabe el precio, achicar fuente
		while ($hPrice > 12 && ($sx + (int)(strlen($priceTxt) * $wPrice * 0.55)) > $xMax) {
			$hPrice--;
			$wPrice = (int)round($hPrice * 0.7);
		}
		$zpl .= "^FO" . $sx . "," . $y . "^A0N," . $hPrice . "," . $wPrice . "^FD" . zpl_escape_field($priceTxt) . "^FS\n";
		$codeX = $sx + (int)(strlen($priceTxt) * $wPrice * 0.55) + 6;
		$hCode = min(15, max(11, $hPrice - 5));
		if ($codeX + 52 <= $xMax) {
			$zpl .= "^FO" . $codeX . "," . ($y + 2) . "^A0N," . $hCode . "," . $hCode . "^FD" . zpl_escape_field($codeTxt) . "^FS\n";
		} else {
			$y += $hPrice + 1;
			if ($y + $hCode <= $sy + $sh) {
				$zpl .= "^FO" . $sx . "," . $y . "^A0N," . $hCode . "," . $hCode . "^FD" . zpl_escape_field($codeTxt) . "^FS\n";
			}
		}
		$y += $hPrice + 2;
	} else {
		$hCode = 13;
		$zpl .= "^FO" . $sx . "," . $y . "^A0N," . $hCode . "," . $hCode . "^FD" . zpl_escape_field($codeTxt) . "^FS\n";
		$y += $hCode + 2;
	}

	$hMeta = min(13, max(10, (int)floor($sh * 0.20)));
	$wMeta = (int)round($hMeta * 0.55);
	if ($y + $hMeta > $sy + $sh) {
		$y = max($sy, $sy + $sh - ($hMeta * 2) - 2);
	}

	if ($expir != 0) {
		$diaexp = date('d/m/Y', strtotime('+' . $expir . ' days', $base));
		$expTxt = 'EXP:' . $diaexp;
		$zpl .= "^FO" . $sx . "," . $y . "^A0N," . $hMeta . "," . $wMeta . "^FD" . zpl_escape_field($expTxt) . "^FS\n";
		$loteTxt = 'Lote:' . etiqueta10_lote_code($base);
		$loteX = $sx + (int)(strlen($expTxt) * $wMeta * 0.62) + 6;
		if ($loteX + 48 <= $xMax) {
			$zpl .= "^FO" . $loteX . "," . $y . "^A0N," . $hMeta . "," . $wMeta . "^FD" . zpl_escape_field($loteTxt) . "^FS\n";
			$y += $hMeta + 1;
		} else {
			$y += $hMeta + 1;
			if ($y + $hMeta <= $sy + $sh) {
				$zpl .= "^FO" . $sx . "," . $y . "^A0N," . $hMeta . "," . $wMeta . "^FD" . zpl_escape_field($loteTxt) . "^FS\n";
				$y += $hMeta + 1;
			}
		}
	}

	if ($reg !== '' && $reg !== '0') {
		if ($y + $hMeta > $sy + $sh) {
			$y = $sy + $sh - $hMeta;
		}
		$zpl .= "^FO" . $sx . "," . $y . "^A0N," . $hMeta . "," . $wMeta . "^FD" . zpl_escape_field('Reg:' . $reg) . "^FS\n";
	}

	return array(
		'zpl' => $zpl,
		'meta' => array(
			'side' => $side,
			'sideW' => $sideW,
			'barH' => $barH,
			'slot' => $slot,
			'empty' => $empty,
			'auto' => true,
		),
	);
}

input.old_string:
/**
 * Busca el mayor rectángulo casi blanco (para poner datos variables sobre el BMP).
 * Prefiere zona inferior (y opcionalmente izquierda).
 *
 * @return array{x:int,y:int,w:int,h:int}|null
 */
function etiqueta10_find_white_rect($bits, $preferLeft = true)
{
	$w = $bits['w'];
	$h = $bits['h'];
	if ($w < 20 || $h < 20) {
		return null;
	}
	$maxInk = 0.08;
	$best = null;
	$bestArea = 0;
	$y0 = (int)floor($h * 0.35); // solo mitad/inferior del arte
	$step = max(2, (int)floor(min($w, $h) / 40));

	for ($top = $y0; $top < $h - 18; $top += $step) {
		for ($bot = $h - 1; $bot > $top + 16; $bot -= $step) {
			$rh = $bot - $top + 1;
			// filas candidatas: deben ser mayormente blancas
			$bad = false;
			for ($y = $top; $y <= $bot; $y += max(1, (int)floor($rh / 8))) {
				if (etiqueta10_row_ink($bits, $y) > $maxInk * 2.5) {
					$bad = true;
					break;
				}
			}
			if ($bad) {
				continue;
			}
			$xStart = $preferLeft ? 0 : (int)floor($w * 0.15);
			$xEnd = $preferLeft ? (int)floor($w * 0.72) : $w - 1;
			for ($left = $xStart; $left < $xEnd - 40; $left += $step) {
				for ($right = $xEnd; $right > $left + 40; $right -= $step) {
					$rw = $right - $left + 1;
					$ink = 0;
					$samples = 0;
					for ($y = $top; $y <= $bot; $y += max(1, (int)floor($rh / 6))) {
						for ($x = $left; $x <= $right; $x += max(1, (int)floor($rw / 8))) {
							$samples++;
							if ($bits['p'][$y * $w + $x] !== "\x00") {
								$ink++;
							}
						}
					}
					if ($samples < 1) {
						continue;
					}
					if (($ink / (float)$samples) > $maxInk) {
						continue;
					}
					$area = $rw * $rh;
					// bonus zona baja e izquierda
					$bonus = 1.0 + (0.35 * ($top / (float)$h)) + ($preferLeft ? (0.15 * (1.0 - ($left / (float)$w))) : 0);
					$score = $area * $bonus;
					if ($score > $bestArea) {
						$bestArea = $score;
						$best = array('x' => $left, 'y' => $top, 'w' => $rw, 'h' => $rh);
					}
					break; // primer right válido lo bastante ancho
				}
			}
		}
	}
	return $best;
}

/**
 * Layout automático:
 * - BMP ocupa casi toda la etiqueta
 * - Solo una franja fina lateral para barcode mínimo
 * - Precio / código / EXP / lote / reg se colocan en huecos blancos del BMP
 *
 * @return array{zpl:string,meta:array}
 */
function etiqueta10_auto_layout_zpl($srcBits, $pw, $ll, $barData, $ctx)
{
	$pw = max(80, (int)$pw);
	$ll = max(60, (int)$ll);

	$preview = etiqueta10_resize_stretch($srcBits, $pw, $ll);
	$empty = etiqueta10_measure_empty($preview);

	// Franja mínima para barcode (no comerse el BMP)
	$side = 'left';
	if ((int)$empty['right'] > (int)$empty['left'] + 15) {
		$side = 'right';
	}
	$barH = 22; // grosor útil mínimo del barcode rotado
	$sideW = $barH + 6; // ~28 dots

	$gap = 2;
	$artW = $pw - $sideW - $gap;
	$artH = $ll; // casi toda la altura = el BMP
	$artX = ($side === 'left') ? ($sideW + $gap) : 0;
	$artY = 0;

	// Arte a casi toda la etiqueta (sin banda inferior reservada)
	$artBits = etiqueta10_resize_stretch($srcBits, $artW, $artH);
	$gfa = etiqueta10_to_gfa($artBits);
	$ox = $artX;
	$oy = $artY;

	$zpl = '';
	$zpl .= "^FO" . $ox . "," . $oy . "^GFA," . $gfa['total'] . "," . $gfa['total'] . "," . $gfa['bpr'] . "," . $gfa['hex'] . "^FS\n";

	// Barcode fino lateral
	$barX = ($side === 'left') ? 2 : ($pw - $sideW + 2);
	$barY = 4;
	$zpl .= "^FO" . $barX . "," . $barY . "^BY1,2," . $barH . "\n";
	$zpl .= "^BCR," . $barH . ",N,N,N\n^FD" . $barData . "^FS\n";

	$itemid = isset($ctx['itemid']) ? etiqueta10_pad_codigo($ctx['itemid']) : $barData;
	$codeTxt = '[' . $itemid . ']';
	$precio = isset($ctx['precio']) ? (float)$ctx['precio'] : 0;
	$expir = isset($ctx['expir']) ? (int)$ctx['expir'] : 0;
	$reg = isset($ctx['reg_sanitario']) ? trim((string)$ctx['reg_sanitario']) : '';
	$base = etiqueta10_parse_fecha(isset($ctx['fecha_manufact']) ? $ctx['fecha_manufact'] : '');
	if ($base === false) {
		$base = time();
	}

	// Hueco blanco DENTRO del BMP para los datos (no recorta el arte)
