/**
 * PNG local (sin Labelary) a partir del buffer 1-bit de la etiqueta.
 * @param array $bits
 * @param array $barBox optional x,y,w,h,use
 * @return string|false PNG bytes
 */
function etiqueta10_label_bits_to_png($bits, $barBox = null)
{
	if (!function_exists('imagecreatetruecolor') || empty($bits['p'])) {
		return false;
	}
	$w = (int)$bits['w'];
	$h = (int)$bits['h'];
	if ($w < 1 || $h < 1 || $w > 4000 || $h > 4000) {
		return false;
	}
	$im = imagecreatetruecolor($w, $h);
	if (!$im) {
		return false;
	}
	$white = imagecolorallocate($im, 255, 255, 255);
	$black = imagecolorallocate($im, 0, 0, 0);
	$gray = imagecolorallocate($im, 40, 40, 40);
	imagefill($im, 0, 0, $white);
	$p = $bits['p'];
	for ($y = 0; $y < $h; $y++) {
		$off = $y * $w;
		for ($x = 0; $x < $w; $x++) {
			if ($p[$off + $x] !== "\x00") {
				imagesetpixel($im, $x, $y, $black);
			}
		}
	}
	if (is_array($barBox) && !empty($barBox['use'])) {
		$bx = (int)$barBox['x'];
		$by = (int)$barBox['y'];
		$bw = (int)$barBox['w'];
		$bh = (int)$barBox['h'];
		if ($bw > 4 && $bh > 4) {
			imagefilledrectangle($im, $bx, $by, $bx + $bw - 1, $by + $bh - 1, $gray);
		}
	}
	ob_start();
	imagepng($im);
	$png = ob_get_clean();
	imagedestroy($im);
	return $png !== false && $png !== '' ? $png : false;
}

