	} else {
		if (!LAYOUT_STATE.layout.fields) LAYOUT_STATE.layout.fields = {};
		if (!LAYOUT_STATE.layout.fields[key]) LAYOUT_STATE.layout.fields[key] = {};
		LAYOUT_STATE.layout.fields[key].x = x;
